      backup_text =
        "# GAME OF LIFE MVU #\n\
         # A night garden that grows by Conway's rules: click cells to sow #\n\n\
         type Cell = + Dead + Alive in\n\n\
         type Grid = (\n\
        \  cells = [Cell],\n\
        \  width = Int,\n\
        \  height = Int\n\
         ) in\n\n\
         type Action =\n\
        \  + ToggleCell(Int)\n\
        \  + Step\n\
        \  + ToggleRunning\n\
        \  + Reset\n\
        \  + Glider\n\
         in\n\n\
         # Grid operations #\n\
         let makeGrid(w: Int, h: Int) : Grid =\n\
        \    (cells = map(range(0, w * h - 1), fun _ -> Dead), width = w, \
         height = h)\n\
         in\n\n\
         let toIndex(g: Grid, x: Int, y: Int) : Int =\n\
        \  y * g.width + x\n\
         in\n\n\
         let inBounds(g: Grid, x: Int, y: Int) : Bool =\n\
        \  x >= 0 && x < g.width && y >= 0 && y < g.height\n\
         in\n\n\
         let getCell(g: Grid, x: Int, y: Int) : Cell =\n\
        \    if inBounds(g, x, y) then nth(g.cells, toIndex(g, x, y)) else Dead\n\
         in\n\n\
         let setCell(g: Grid, x: Int, y: Int, cell: Cell) : Grid =\n\
        \    let idx = toIndex(g, x, y) in\n\
        \    (cells = mapi(g.cells, fun (i, c) -> if i == idx then cell else c),\n\
        \     width = g.width, height = g.height)\n\
         in\n\n\
         let countNeighbors(g: Grid, x: Int, y: Int) : Int =\n\
        \    length(filter([\n\
        \      getCell(g, x - 1, y - 1), getCell(g, x, y - 1), getCell(g, x + \
         1, y - 1),\n\
        \      getCell(g, x - 1, y),                             getCell(g, x \
         + 1, y),\n\
        \      getCell(g, x - 1, y + 1), getCell(g, x, y + 1), getCell(g, x + \
         1, y + 1)\n\
        \    ], fun c -> c == Alive))\n\
         in\n\n\
         let nextCellState(current: Cell, neighbors: Int) : Cell =\n\
        \    case current\n\
        \    | Alive => if neighbors == 2 || neighbors == 3 then Alive else Dead\n\
        \    | Dead => if neighbors == 3 then Alive else Dead\n\
        \    end\n\
         in\n\n\
         let stepGrid(g: Grid) : Grid =\n\
        \    let newCells = mapi(g.cells, fun (idx, _) ->\n\
        \      let x = int_mod(idx, g.width) in\n\
        \      let y = idx / g.width in\n\
        \      nextCellState(getCell(g, x, y), countNeighbors(g, x, y))\n\
        \    ) in\n\
        \    (cells = newCells, width = g.width, height = g.height)\n\
         in\n\n\
         let setAlive(g: Grid, coords: [(Int, Int)]) : Grid =\n\
        \    fold_left(coords, (fun (grid, xy) ->\n\
        \      let (x, y) = xy in setCell(grid, x, y, Alive)\n\
        \    ), g)\n\
         in\n\n\
         let countAlive(g: Grid) : Int =\n\
        \  length(filter(g.cells, fun c -> c == Alive))\n\
         in\n\n\
         let runGrid(g: Grid, n: Int) : Grid =\n\
        \    if n <= 0 then g\n\
        \    else fold_left(range(1, n), (fun (grid, _) -> stepGrid(grid)), g)\n\
         in\n\n\
         # Glider pattern at (1,1) #\n\
         let placeGlider(grid: Grid) : Grid =\n\
        \  setAlive(grid, [(2, 1), (3, 2), (1, 3), (2, 3), (3, 3)])\n\
         in\n\n\
         let gridSize = 8 in\n\n\
         let init = (\n\
        \  grid = makeGrid(gridSize, gridSize),\n\
        \  running = false,\n\
        \  generation = 0\n\
         ) in\n\n\
         let update(action, model) =\n\
        \  case action\n\
        \  | ToggleCell(idx) =>\n\
        \      let cell = nth(model.grid.cells, idx) in\n\
        \      let newCell = case cell | Alive => Dead | Dead => Alive end in\n\
        \      let newCells = mapi(model.grid.cells, fun (i, c) ->\n\
        \        if i == idx then newCell else c) in\n\
        \      let newGrid = (cells=newCells, width=model.grid.width, \
         height=model.grid.height) in\n\
        \      ((grid=newGrid, running=model.running, \
         generation=model.generation), CmdNone)\n\
        \  | Step =>\n\
        \      ((grid=stepGrid(model.grid), running=model.running,\n\
        \        generation=model.generation + 1), CmdNone)\n\
        \  | ToggleRunning =>\n\
        \      let nowRunning = if model.running then false else true in\n\
        \      ((grid=model.grid, running=nowRunning, \
         generation=model.generation), CmdNone)\n\
        \  | Reset => (init, CmdNone)\n\
        \  | Glider =>\n\
        \      ((grid=placeGlider(model.grid), running=model.running,\n\
        \        generation=model.generation), CmdNone)\n\
        \  end\n\
         in\n\n\
         let cellColor(cell) =\n\
        \  case cell | Alive => \"#39ff14\" | Dead => \"#0d0d1a\" end\n\
         in\n\n\
         let view(model) =\n\
        \  Div(\n\
        \    [Style([(\"max-width\", \"400px\"), (\"margin\", \"20px auto\"), \
         (\"text-align\", \"center\"),\n\
        \            (\"font-family\", \"monospace\"), (\"background\", \
         \"#0a0a14\"), (\"padding\", \"20px\"),\n\
        \            (\"border-radius\", \"8px\"), (\"color\", \"#ccc\")])],\n\
        \    [\n\
        \      H2([Style([(\"color\", \"#39ff14\"), (\"margin-bottom\", \
         \"2px\")])], [Text(\"\240\159\140\177 Garden of Life\")]),\n\
        \      P([Style([(\"font-size\", \"12px\"), (\"color\", \"#8b949e\"), \
         (\"margin-top\", \"0\")])], [Text(\"Sow a cell; the grove spreads by \
         Conway's rules\")]),\n\
        \      P([], [Text(\"Generation: \" ++ \
         string_of_int(model.generation))]),\n\
        \      # Grid using Table #\n\
        \      Table(\n\
        \        [Style([(\"border-collapse\", \"collapse\"), (\"margin\", \
         \"10px auto\")])],\n\
        \        map(range(0, model.grid.height - 1), fun y ->\n\
        \          Tr([], map(range(0, model.grid.width - 1), fun x ->\n\
        \            let idx = y * model.grid.width + x in\n\
        \            let cell = nth(model.grid.cells, idx) in\n\
        \            Td(\n\
        \              [\n\
        \                OnClick(ToggleCell(idx)),\n\
        \                Style([\n\
        \                  (\"width\", \"20px\"), (\"height\", \"20px\"),\n\
        \                  (\"border\", \"1px solid #1a1a2e\"),\n\
        \                  (\"cursor\", \"pointer\"),\n\
        \                  (\"background\", cellColor(cell)),\n\
        \                  (\"transition\", \"background 0.1s\")\n\
        \                ])\n\
        \              ],\n\
        \              []\n\
        \            )\n\
        \          ))\n\
        \        )\n\
        \      ),\n\
        \      # Controls #\n\
        \      Div(\n\
        \        [Style([(\"margin-top\", \"15px\"), (\"display\", \"flex\"),\n\
        \                (\"justify-content\", \"center\"), (\"gap\", \
         \"8px\")])],\n\
        \        [\n\
        \          Button(\n\
        \            [OnClick(Step),\n\
        \             Style([(\"padding\", \"8px 16px\"), (\"background\", \
         \"#2196F3\"),\n\
        \                    (\"color\", \"white\"), (\"border\", \"none\"), \
         (\"cursor\", \"pointer\"),\n\
        \                    (\"border-radius\", \"4px\")])],\n\
        \            [Text(\"Step\")]\n\
        \          ),\n\
        \          Button(\n\
        \            [OnClick(ToggleRunning),\n\
        \             Style([(\"padding\", \"8px 16px\"),\n\
        \                    (\"background\", if model.running then \
         \"#ff9800\" else \"#4CAF50\"),\n\
        \                    (\"color\", \"white\"), (\"border\", \"none\"), \
         (\"cursor\", \"pointer\"),\n\
        \                    (\"border-radius\", \"4px\")])],\n\
        \            [Text(if model.running then \"Pause\" else \"Run\")]\n\
        \          ),\n\
        \          Button(\n\
        \            [OnClick(Glider),\n\
        \             Style([(\"padding\", \"8px 16px\"), (\"background\", \
         \"#9C27B0\"),\n\
        \                    (\"color\", \"white\"), (\"border\", \"none\"), \
         (\"cursor\", \"pointer\"),\n\
        \                    (\"border-radius\", \"4px\")])],\n\
        \            [Text(\"Glider\")]\n\
        \          ),\n\
        \          Button(\n\
        \            [OnClick(Reset),\n\
        \             Style([(\"padding\", \"8px 16px\"), (\"background\", \
         \"#f44336\"),\n\
        \                    (\"color\", \"white\"), (\"border\", \"none\"), \
         (\"cursor\", \"pointer\"),\n\
        \                    (\"border-radius\", \"4px\")])],\n\
        \            [Text(\"Reset\")]\n\
        \          )\n\
        \        ]\n\
        \      )\n\
        \    ]\n\
        \  )\n\
         in\n\n\
         let subs(model) =\n\
        \  if model.running then Every(400.0, fun _ts -> Step) else SubNone\n\
         in\n\n\
         # Test helpers #\n\
         let do_step(acc, a) = let (m, _) = update(a, acc) in m in\n\
         let do_actions(m, actions) = fold_left(actions, do_step, m) in\n\n\
         # Tests #\n\n\
         hint \"empty grid has all dead cells\"\n\
         test countAlive(makeGrid(3, 3)) == 0 end;\n\n\
         hint \"can set and get cell\"\n\
         test getCell(setCell(makeGrid(3, 3), 1, 1, Alive), 1, 1) == Alive \
         end;\n\n\
         hint \"out of bounds returns Dead\"\n\
         test\n\
        \  let g = makeGrid(3, 3) in\n\
        \  getCell(g, -1, 0) == Dead && getCell(g, 5, 5) == Dead\n\
         end;\n\n\
         hint \"isolated cell has 0 neighbors\"\n\
         test countNeighbors(setAlive(makeGrid(5, 5), [(2, 2)]), 2, 2) == 0 \
         end;\n\n\
         hint \"cell with one neighbor\"\n\
         test countNeighbors(setAlive(makeGrid(5, 5), [(2, 2), (2, 3)]), 2, 2) \
         == 1 end;\n\n\
         hint \"alive with 2 neighbors survives\"\n\
         test\n\
        \  let g = setAlive(makeGrid(3, 3), [(0, 1), (1, 1), (2, 1)]) in\n\
        \  getCell(stepGrid(g), 1, 1) == Alive\n\
         end;\n\n\
         hint \"alive with 1 neighbor dies\"\n\
         test\n\
        \  let g = setAlive(makeGrid(3, 3), [(1, 1), (1, 0)]) in\n\
        \  getCell(stepGrid(g), 1, 1) == Dead\n\
         end;\n\n\
         hint \"dead with 3 neighbors born\"\n\
         test\n\
        \  let g = setAlive(makeGrid(3, 3), [(0, 0), (1, 0), (0, 1)]) in\n\
        \  getCell(stepGrid(g), 1, 1) == Alive\n\
         end;\n\n\
         hint \"blinker oscillates\"\n\
         test\n\
        \  let g = setAlive(makeGrid(5, 5), [(1, 2), (2, 2), (3, 2)]) in\n\
        \  let g2 = stepGrid(g) in\n\
        \  getCell(g2, 2, 1) == Alive && getCell(g2, 2, 2) == Alive && \
         getCell(g2, 2, 3) == Alive\n\
         end;\n\n\
         hint \"blinker returns after 2 steps\"\n\
         test\n\
        \  let g = setAlive(makeGrid(5, 5), [(1, 2), (2, 2), (3, 2)]) in\n\
        \  let g2 = runGrid(g, 2) in\n\
        \  getCell(g2, 1, 2) == Alive && getCell(g2, 2, 2) == Alive && \
         getCell(g2, 3, 2) == Alive\n\
         end;\n\n\
         hint \"block is stable\"\n\
         test\n\
        \  let g = setAlive(makeGrid(4, 4), [(1, 1), (2, 1), (1, 2), (2, 2)]) in\n\
        \  countAlive(stepGrid(g)) == 4\n\
         end;\n\n\
         hint \"simultaneous update\"\n\
         test\n\
        \  let g = setAlive(makeGrid(5, 5), [(1, 2), (2, 2), (3, 2)]) in\n\
        \  let g2 = stepGrid(g) in\n\
        \  getCell(g2, 1, 2) == Dead && getCell(g2, 3, 2) == Dead\n\
         end;\n\n\
         hint \"toggle cell via update\"\n\
         test\n\
        \  let m = do_actions(init, [ToggleCell(0)]) in\n\
        \  nth(m.grid.cells, 0) == Alive\n\
         end;\n\n\
         hint \"step increments generation\"\n\
         test\n\
        \  let m = do_actions(init, [Step, Step]) in\n\
        \  m.generation == 2\n\
         end;\n\n\
         hint \"reset clears grid\"\n\
         test\n\
        \  let m = do_actions(init, [ToggleCell(0), ToggleCell(5), Reset]) in\n\
        \  countAlive(m.grid) == 0 && m.generation == 0\n\
         end;\n\n\
         hint \"glider places 5 cells\"\n\
         test\n\
        \  let m = do_actions(init, [Glider]) in\n\
        \  countAlive(m.grid) == 5\n\
         end;\n\n\
         (init, update, view, subs)\n";
      refractors = "()";
